activities.acceptanceScript:
const q = (id) => page.locator(`[data-testid="${id}"]`);
await page.goto(BASE_URL + '/activities/gear-lock-facts');
await q('gear-chamber').waitFor({state:'visible'});
const arcBefore = await q('progress-arc').getAttribute('data-filled');
if (arcBefore !== '0') throw new Error('Progress arc should start at 0');

// Attempt incorrect drag on gear 1 (5 x 2 = 10): drag wrong tooth '7'
const wrongTooth = q('gear-tooth-7');
const gear1Notch = q('gear-notch-gear1');
await wrongTooth.dispatchEvent('dragstart');
await gear1Notch.dispatchEvent('dragenter');
await gear1Notch.dispatchEvent('dragover');
await gear1Notch.dispatchEvent('drop');
await wrongTooth.dispatchEvent('dragend');
const recovery = q('recovery-hint-gear1');
await recovery.waitFor({state:'visible'});
const arcAfterWrong = await q('progress-arc').getAttribute('data-filled');
if (arcAfterWrong !== '0') throw new Error('Progress should not advance on incorrect drop');
const gear1Locked = await q('gear1').getAttribute('data-locked');
if (gear1Locked === 'true') throw new Error('Gear should not lock on incorrect answer');

// Correct drag for gear 1
const rightTooth10 = q('gear-tooth-10');
await rightTooth10.dispatchEvent('dragstart');
await gear1Notch.dispatchEvent('dragenter');
await gear1Notch.dispatchEvent('dragover');
await gear1Notch.dispatchEvent('drop');
await rightTooth10.dispatchEvent('dragend');
await page.waitForFunction(() => document.querySelector('[data-testid="gear1"]')?.getAttribute('data-locked') === 'true');
let arc = await q('progress-arc').getAttribute('data-filled');
if (arc !== '1') throw new Error('Progress arc should be 1 after gear1 locked');

const answers = [
  {gear:'gear2', tooth:'gear-tooth-25', notch:'gear-notch-gear2'},
  {gear:'gear3', tooth:'gear-tooth-50', notch:'gear-notch-gear3'},
  {gear:'gear4', tooth:'gear-tooth-14', notch:'gear-notch-gear4'},
  {gear:'gear5', tooth:'gear-tooth-40', notch:'gear-notch-gear5'}
];
for (const a of answers) {
  const tooth = q(a.tooth);
  const notch = q(a.notch);
  await tooth.dispatchEvent('dragstart');
  await notch.dispatchEvent('dragenter');
  await notch.dispatchEvent('dragover');
  await notch.dispatchEvent('drop');
  await tooth.dispatchEvent('dragend');
  await page.waitForFunction((g) => document.querySelector(`[data-testid="${g}"]`)?.getAttribute('data-locked') === 'true', a.gear);
}

const finalArc = await q('progress-arc').getAttribute('data-filled');
if (finalArc !== '5') throw new Error('All 5 gears should be locked');
const doorState = await q('chamber-door').getAttribute('data-open');
if (doorState !== 'true') throw new Error('Chamber door should be open after all gears locked');
await q('completion-banner').waitFor({state:'visible'});
return {passed:true};

const q = (id) => page.locator(`[data-testid="${id}"]`);
await page.goto(BASE_URL + '/activities/gear-lock-word-problems');
await q('story-gear-pencils').waitFor({state:'visible'});
const arcStart = await q('story-progress-arc').getAttribute('data-filled');
if (arcStart !== '0') throw new Error('Story progress should start at 0');

const wrongTooth = q('gear-tooth-9');
const pencilNotch = q('gear-notch-pencils');
await wrongTooth.dispatchEvent('dragstart');
await pencilNotch.dispatchEvent('dragenter');
await pencilNotch.dispatchEvent('dragover');
await pencilNotch.dispatchEvent('drop');
await wrongTooth.dispatchEvent('dragend');
await q('recovery-pulse-pencils').waitFor({state:'visible'});
const lockedWrong = await q('story-gear-pencils').getAttribute('data-locked');
if (lockedWrong === 'true') throw new Error('Pencil gear should not lock on wrong answer');

const rightTooth20 = q('gear-tooth-20');
await rightTooth20.dispatchEvent('dragstart');
await pencilNotch.dispatchEvent('dragenter');
await pencilNotch.dispatchEvent('dragover');
await pencilNotch.dispatchEvent('drop');
await rightTooth20.dispatchEvent('dragend');
await page.waitForFunction(() => document.querySelector('[data-testid="story-gear-pencils"]')?.getAttribute('data-locked') === 'true');
let arc = await q('story-progress-arc').getAttribute('data-filled');
if (arc !== '1') throw new Error('Progress should be 1 after pencil gear locked');

const rightTooth30 = q('gear-tooth-30');
const starNotch = q('gear-notch-stars');
await rightTooth30.dispatchEvent('dragstart');
await starNotch.dispatchEvent('dragenter');
await starNotch.dispatchEvent('dragover');
await starNotch.dispatchEvent('drop');
await rightTooth30.dispatchEvent('dragend');
await page.waitForFunction(() => document.querySelector('[data-testid="story-gear-stars"]')?.getAttribute('data-locked') === 'true');

const finalArc = await q('story-progress-arc').getAttribute('data-filled');
if (finalArc !== '2') throw new Error('Both story gears should be locked');
const alcoveOpen = await q('inner-vault-alcove').getAttribute('data-open');
if (alcoveOpen !== 'true') throw new Error('Inner vault alcove should open after both gears locked');
await q('completion-banner').waitFor({state:'visible'});
return {passed:true};

const q = (id) => page.locator(`[data-testid="${id}"]`);
await page.goto(BASE_URL + '/activities/comet-run-facts');
await q('comet-track').waitFor({state:'visible'});
const trailStart = await q('trail-meter').getAttribute('data-lit');
if (trailStart !== '0') throw new Error('Trail meter should start at 0');

const wrongOrb = q('orb-seal1-7');
await wrongOrb.dispatchEvent('pointerdown');
await wrongOrb.dispatchEvent('pointerup');
await q('comet-loop-indicator').waitFor({state:'visible'});
const trailAfterWrong = await q('trail-meter').getAttribute('data-lit');
if (trailAfterWrong !== '0') throw new Error('Trail should not advance on incorrect tap');

const rightOrb1 = q('orb-seal1-10');
await rightOrb1.dispatchEvent('pointerdown');
await rightOrb1.dispatchEvent('pointerup');
await page.waitForFunction(() => document.querySelector('[data-testid="trail-meter"]')?.getAttribute('data-lit') === '1');

const seals = [
  {orb:'orb-seal2-25'},
  {orb:'orb-seal3-50'},
  {orb:'orb-seal4-14'},
  {orb:'orb-seal5-40'}
];
let i = 2;
for (const s of seals) {
  const orb = q(s.orb);
  await orb.dispatchEvent('pointerdown');
  await orb.dispatchEvent('pointerup');
  const expected = String(i);
  await page.waitForFunction((exp) => document.querySelector('[data-testid="trail-meter"]')?.getAttribute('data-lit') === exp, expected);
  i++;
}

const finalTrail = await q('trail-meter').getAttribute('data-lit');
if (finalTrail !== '5') throw new Error('All 5 trail segments should be lit');
const cometArrived = await q('comet-track').getAttribute('data-arrived');
if (cometArrived !== 'true') throw new Error('Comet should have arrived at final seal');
await q('completion-banner').waitFor({state:'visible'});
return {passed:true};

const q = (id) => page.locator(`[data-testid="${id}"]`);
await page.goto(BASE_URL + '/activities/comet-run-word-problems');
await q('story-comet-track').waitFor({state:'visible'});
const trailStart = await q('story-trail-meter').getAttribute('data-lit');
if (trailStart !== '0') throw new Error('Story trail meter should start at 0');

const wrongOrb = q('orb-pencils-9');
await wrongOrb.dispatchEvent('pointerdown');
await wrongOrb.dispatchEvent('pointerup');
await q('comet-loop-indicator').waitFor({state:'visible'});
const trailAfterWrong = await q('story-trail-meter').getAttribute('data-lit');
if (trailAfterWrong !== '0') throw new Error('Trail should not advance on incorrect tap');

const rightOrbPencils = q('orb-pencils-20');
await rightOrbPencils.dispatchEvent('pointerdown');
await rightOrbPencils.dispatchEvent('pointerup');
await page.waitForFunction(() => document.querySelector('[data-testid="story-trail-meter"]')?.getAttribute('data-lit') === '1');

const rightOrbStars = q('orb-stars-30');
await rightOrbStars.dispatchEvent('pointerdown');
await rightOrbStars.dispatchEvent('pointerup');
await page.waitForFunction(() => document.querySelector('[data-testid="story-trail-meter"]')?.getAttribute('data-lit') === '2');

const finalTrail = await q('story-trail-meter').getAttribute('data-lit');
if (finalTrail !== '2') throw new Error('Both story trail segments should be lit');
const cometArrived = await q('story-comet-track').getAttribute('data-arrived');
if (cometArrived !== 'true') throw new Error('Comet should have arrived at final story seal');
const alcoveOpen = await q('story-alcove').getAttribute('data-open');
if (alcoveOpen !== 'true') throw new Error('Story alcove should open after both seals lit');
await q('completion-banner').waitFor({state:'visible'});
return {passed:true};
